CREATE TABLE IF NOT EXISTS question_answer (
                                 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                 question VARCHAR(1000) NOT NULL,
                                 answer VARCHAR(5000) NOT NULL
);

INSERT INTO question_answer (question, answer) VALUES
-- 1
('По каким причинам студента могут отчислить из университета?',
 'Студент может быть отчислен:
 - в случае невыполнения обязанностей по добросовестному освоению образовательной программы и выполнению учебного плана;
 - в случае установления нарушения порядка приема в Университет, повлекшего по вине обучающегося его незаконное зачисление в Университет;
 - в случае просрочки оплаты стоимости платных образовательных услуг;
 - в случае, если надлежащее исполнение обязательства по оказанию платных образовательных услуг стало невозможным вследствие действий (бездействия) обучающегося.'),

-- 2
('Что делать, если студент хочет отчислиться добровольно?',
 'Основанием для отчисления по собственному желанию, в том числе по состоянию здоровья, в связи с призывом в Вооруженные силы РФ, является письменное заявление по установленной форме, подаваемое в деканат факультета/дирекцию института (филиала)/Многопрофильного колледжа, с приложением документов, подтверждающих причины отчисления, указанные в заявлении (медицинская справка, подтверждающая факт невозможности продолжения обучения; документ из военного комиссариата; иные документы (при наличии)).
 Заявление об отчислении согласовывается с деканом факультета/директором института (филиала)/Многопрофильного колледжа, Департаментом образовательной политики, Управлением международных связей (в случае отчисления иностранных обучающихся), Департаментом экономического развития приоритетных проектов и платных образовательных услуг (в случае отчисления обучающихся на платной основе).'),

-- 3
('Могут ли отчислить студента, если он имеет только одну задолженность?',
 'Да, могут. Отчисление осуществляется в том числе, если:
 - обучающийся, имеющий академическую задолженность, не ликвидировал ее в установленные сроки (до 15 апреля – после зимней экзаменационной сессии, до 15 ноября – после летней экзаменационной сессии);
 - обучающийся не прошел итоговое (государственное итоговое) аттестационное испытание в связи с неявкой на итоговое (государственное итоговое) аттестационное испытание по неуважительной причине;
 - обучающийся не прошел одно и более итоговое (государственное итоговое) аттестационное испытание;
 - обучающийся без уважительных причин не посещал учебные занятия в течение 30 (тридцати) календарных дней подряд;
 - обучающийся не посещал в течение семестра более 25% учебных занятий по отдельным дисциплинам, предусмотренным учебным планом или индивидуальным учебным планом;
 - обучающийся не ликвидировал академическую задолженность, возникшую при ликвидации академической разницы в учебных планах, в установленные приказом сроки;
 - обучающийся не вышел из академического отпуска (отпуска по беременности и родам, отпуска по уходу за ребенком) без уважительной причины после окончания отпуска в течение установленного времени.'),

-- 4
('Могут ли отчислить студента во время болезни?',
 'Нет, не могут.
 Не допускается отчисление обучающегося по инициативе Университета во время его болезни, каникул, академического отпуска, отпуска по беременности и родам, отпуска по уходу за ребенком.'),

-- 5
('Кто имеет право на восстановление в вузе?',
 'Лицо, отчисленное из Университета по инициативе обучающегося до завершения освоения образовательной программы, имеет право на восстановление в Университет в течение пяти лет после отчисления из него, но не ранее завершения учебного года (семестра), в котором указанное лицо было отчислено, с сохранением (при наличии вакантных мест) той основы обучения (бесплатная или платная основа), в соответствии с которой он обучался до отчисления.
 Лицо, отчисленное из Университета по инициативе Университета до завершения освоения образовательной программы, имеет право на восстановление в Университет на платную основу (при наличии вакантных мест) в течение пяти лет после отчисления из него, но не ранее завершения учебного года (семестра), в котором указанное лицо было отчислено.
 На восстановление в Университет (один раз) на бесплатную основу обучения (при наличии вакантных бюджетных мест) в течение пяти лет после отчисления из него, но не ранее завершения учебного года (семестра), в котором лицо было отчислено, могут претендовать следующие лица, отчисленные по инициативе Университета:
 - дети-сироты;
 - дети, оставшиеся без попечения родителей;
 - лица из числа детей-сирот и детей, оставшихся без попечения родителей;
 - лица, потерявшие в период обучения обоих родителей или единственного родителя;
 - инвалиды и лица с ограниченными возможностями здоровья;
 - лица, имеющие статус участника специальной военной операции, и члены семьи лиц, имеющих статус участника специальной военной операции.'),

-- 6
('Кто может быть восстановлен на бесплатную основу обучения?',
 'Лицо, отчисленное из Университета по инициативе обучающегося до завершения освоения образовательной программы, имеет право на восстановление в Университет в течение пяти лет после отчисления из него, но не ранее завершения учебного года (семестра), в котором указанное лицо было отчислено, с сохранением бесплатной основы обучения (при наличии вакантных мест).
 На восстановление в Университет (один раз) на бесплатную основу обучения (при наличии вакантных бюджетных мест) в течение пяти лет после отчисления из него, но не ранее завершения учебного года (семестра), в котором лицо было отчислено, могут претендовать следующие лица, отчисленные по инициативе Университета:
 - дети-сироты;
 - дети, оставшиеся без попечения родителей;
 - лица из числа детей-сирот и детей, оставшихся без попечения родителей;
 - лица, потерявшие в период обучения обоих родителей или единственного родителя;
 - инвалиды и лица с ограниченными возможностями здоровья;
 - лица, имеющие статус участника специальной военной операции, и члены семьи лиц, имеющих статус участника специальной военной операции.'),

-- 7
('Какие документы нужны для восстановления?',
 'Восстановление в число обучающихся Университета производится по личному заявлению восстанавливающегося лица приказом ректора (проректора по учебной работе/директора ИДО).
 Заявление о восстановлении, поданное в деканат факультета / дирекцию института (филиала) / Многопрофильного колледжа, рассматривается аттестационной комиссией факультета/института (филиала)/Многопрофильного колледжа в недельный срок. При этом выполняющим обязанности заместителя декана факультета / директора института (филиала) по учебной работе / заместителем директора по учебной работе Многопрофильного колледжа устанавливаются курс обучения, академическая разница в учебных планах и сроки ее ликвидации, а также основа обучения (платная/бесплатная), о чем делается соответствующая запись на заявлении восстанавливающегося. При восстановлении обучающемуся формируется индивидуальный учебный план, предусматривающий объем образовательной программы за один учебный год, включая разницу в учебных планах, с учетом соответствующих образовательных стандартов.
 Заявление о восстановлении согласовывается с деканом факультета/директором института (филиала)/Многопрофильного колледжа, Департаментом образовательной политики, Управлением международных связей (в случае восстановления иностранных обучающихся). При восстановлении на платную основу заявление дополнительно визируется в Департаменте экономического развития приоритетных проектов и платных образовательных услуг, заключается договор об образовании на обучение по образовательным программам высшего образования, программам ординатуры или среднего профессионального образования, и вносится оплата согласно условиям договора.
 Обучающемуся для ликвидации разницы в учебных планах на основании подписанного заявления о восстановлении деканатом факультета/дирекцией института(филиала)/Многопрофильного колледжа выдаются экзаменационные листы с указанием срока ликвидации.
 Обучающийся обязан соблюдать установленные сроки ликвидации разницы в учебных планах.
 Проект приказа о восстановлении подготавливается и направляется на согласование соответствующим структурным подразделением с использованием электронного документооборота в порядке и в сроки, установленные локальным нормативным актом Университета.'),

-- 8
('Что делать, если не прошел ГИА?',
 'Обучающимся, завершившим освоение образовательной программы и не подтвердившим соответствие подготовки требованиям образовательного стандарта при прохождении одного или нескольких итоговых (государственных итоговых) аттестационных испытаний, предоставляется право восстановления в число обучающихся и прохождения повторных итоговых аттестационных испытаний.
 Повторные итоговые аттестационные испытания по программам бакалавриата, специалитета, магистратуры назначаются не ранее чем через 10 месяцев и не позднее чем через пять лет после прохождения итоговой (государственной итоговой) аттестации впервые. Повторные итоговые аттестационные испытания не могут назначаться более двух раз.
 Для прохождения повторных итоговых аттестационных испытаний необходимо подать заявление о восстановлении в состав обучающихся. При этом по решению выпускающей кафедры (выпускающей предметно-цикловой комиссии) может быть сохранена прежняя тема выпускной квалификационной работы или утверждена новая. Данное решение указывается в заявлении восстанавливающегося лица. Восстановление обучающегося для повторного прохождения итоговых аттестационных испытаний производится на период времени, предусмотренный календарным учебным графиком Университета для итоговых аттестационных испытаний по соответствующей образовательной программе.'),

-- 9
('Можно ли перевестись с платной формы обучения на бюджетную?',
 'Да, можно. Перевод обучающихся допускается с любой формы обучения на любую форму обучения.
 Перевод в Университет, как в принимающую организацию, осуществляется при наличии вакантных мест для перевода обучающихся из другой образовательной организации.
 Количество вакантных мест для перевода определяется Университетом с детализацией по образовательным программам, формам обучения, курсам обучения с указанием количества вакантных мест для перевода, финансируемых за счет бюджетных ассигнований федерального бюджета, бюджетов субъектов Российской Федерации, местных бюджетов, по договорам об образовании за счет средств физических и (или) юридических лиц.
 Перевод на обучение за счет бюджетных ассигнований осуществляется:
 - при отсутствии ограничений, предусмотренных для освоения соответствующей образовательной программы за счет бюджетных ассигнований, а также если обучение по соответствующей образовательной программе не является получением второго или последующего соответствующего образования;
 - в случае если общая продолжительность обучения обучающегося не будет превышать более чем на один учебный год срока освоения образовательной программы, на которую он переводится, установленного федеральным государственным образовательным стандартом, федеральными государственными требованиями, образовательным стандартом или требованиями, устанавливаемыми Университетом самостоятельно (с учетом формы обучения и иных оснований, влияющих на срок освоения образовательной программы).'),

-- 10
('Кто может перевестись с платного обучения на бесплатное?',
 'Право на переход с платного обучения на бесплатное имеет лицо, обучающееся в университете на основании договора об образовании за счет средств физического и (или) юридического лица, не имеющее на момент подачи заявления академической задолженности, дисциплинарных взысканий, задолженности по оплате обучения, при наличии одного из следующих условий:
 а) сдачи экзаменов за два последних семестра предшествующих подаче заявления, на оценки «отлично» или «отлично» и «хорошо» или «хорошо»;
 б) отнесения к следующим категориям граждан:
 - детей-сирот и детей, оставшихся без попечения родителей, а также лиц из числа детей-сирот и детей, оставшихся без попечения родителей;
 - граждан в возрасте до двадцати лет, имеющих только одного родителя – инвалида I группы, если среднедушевой доход семьи ниже величины прожиточного минимума, установленного в РМ;
 - женщин, родивших ребенка в период обучения;
 в) утраты обучающимся в период обучения одного или обоих родителей (законных представителей) или единственного родителя (законного представителя).'),

-- 11
('Можно ли перевестись с платного обучения на бесплатное, если учишься на «хорошо» и «удовлетворительно»?',
 'Нет. Право на переход с платного обучения на бесплатное имеет студент, сдавший экзамены за два последних семестра предшествующих подаче заявления, на оценки «отлично» или «отлично» и «хорошо» или «хорошо».'),

-- 12
('Где можно узнать о наличии свободных бюджетных мест для перевода с платного обучения на бесплатное?',
 'Информация о количестве вакантных бюджетных мест для перехода с платного обучения на бесплатное, сроках подачи обучающимися заявлений на переход с платного обучения на бесплатное размещается в информационно-телекоммуникационных сетях, в том числе на официальном сайте университета в сети «Интернет».'),

-- 13
('Куда нужно обратиться, чтобы перевестись с платного обучения на бесплатное?',
 'Обучающийся, желающий перейти на вакантное бюджетное место, представляет в деканат (дирекцию) факультета (института), в котором он обучается, заявление на имя ректора о переходе с платного обучения на бесплатное в течение двух недель после размещения на официальном сайте университета информации о наличии вакантных бюджетных мест.
 К заявлению обучающийся прилагает документы:
 а) подтверждающие отнесение его к особым категориям граждан (дети-сироты; дети, оставшиеся без попечения родителей; граждане в возрасте до двадцати лет, имеющие только одного родителя – инвалида I группы, если среднедушевой доход семьи ниже величины прожиточного минимума, установленного в РМ; женщины, родившие ребенка в период обучения; утратившие в период обучения одного или обоих родителей (законных представителей) или единственного родителя (законного представителя)), т.е. справки о составе семьи, справки из органов социальной защиты, справки об инвалидности;
 в) подтверждающие его особые достижения в учебной, научно-исследовательской, общественной, культурно-творческой и спортивной деятельности университета (грамоты, дипломы, свидетельства, публикации и т.п.).'),

-- 14
('Можно ли перевестись на другой факультет, на другое направление подготовки до первой сессии?',
 'Нет. Перевод обучающихся допускается не ранее чем после прохождения первой промежуточной аттестации в Университете (при переводе внутри Университета или в принимающую организацию) и в исходной организации (при переводе в Университет).'),

-- 15
('Что нужно, чтобы перевестись в МГУ им. Н.П. Огарёва из другого вуза?',
 'Обучающемуся необходимо подать в деканат факультета / дирекцию института (филиала) заявление о переводе на имя проректора по учебной работе с приложением справки о периоде обучения и иных документов, подтверждающих индивидуальные достижения обучающегося.
 Деканат факультета / дирекция института (филиала) оценивает полученные документы на предмет соответствия обучающегося требованиям, предусмотренным в Университете, и определения перечней изученных учебных дисциплин, пройденных практик, выполненных научных исследований, которые в случае перевода обучающегося будут перезачтены или переаттестованы, и определяет период, с которого обучающийся в случае перевода будет допущен к обучению.
 В случае если заявлений о переводе подано больше количества вакантных мест для перевода, деканат факультета / дирекция института (филиала) помимо оценивания полученных документов проводит конкурсный отбор среди лиц, подавших заявления о переводе.
 По результатам конкурсного отбора деканат факультета / дирекция института (филиала) рекомендует принять решение о зачислении на вакантные места для перевода обучающихся, наиболее подготовленных к освоению соответствующей образовательной программы, руководствуясь при этом средним баллом успеваемости, а также совокупностью и значимостью индивидуальных достижений.
 При принятии проректором по учебной работе Университета решения о зачислении обучающемуся выдается справка о переводе, в которой указываются уровень образования, код и наименование профессии, специальности или направления подготовки, куда обучающийся будет переведен. Справка о переводе подписывается проректором по учебной работе Университета и заверяется печатью. К справке прилагается перечень изученных учебных дисциплин, пройденных практик, выполненных научных исследований, которые будут перезачтены или переаттестованы обучающемуся при переводе.
 Данная справка вместе с заявлением о переводе и выпиской из приказа об отчислении в связи с переводом (из исходной организации), а также документом о предшествующем образовании предоставляется в деканат факультета / дирекцию института (филиала), который/-ая готовит проект приказа о зачислении.'),

-- 16
('Как можно перевестись с одной образовательной программы университета на другую?',
 'Перевод осуществляется по личному заявлению обучающегося, поданному на имя проректора по учебной работы Университета и проводится на основе аттестации, которую проводит аттестационная комиссия принимающего факультета (института/филиала).
 Для переаттестации (перезачёта) дисциплин в деканате принимающего факультета (дирекции института/филиала) обучающемуся выдается аттестационная ведомость, в которую вносятся все дисциплины (модули, практики), подлежащие переаттестации (перезачёту).
 Аттестация может проводиться путем собеседования или в иной форме, определяемой соответствующей аттестационной комиссией факультета (института/филиала). В ходе аттестации определяется расхождение в учебных планах (разница в учебных планах образовательных программ), устанавливается перечень дисциплин (модулей, практик), которые комиссия считает возможным переаттестовать (перезачесть), и перечень неизученных дисциплин (разделов дисциплин, модулей, не пройденных практик), по которым обучающемуся необходимо пройти аттестационные испытания. Аттестационной комиссией определяются сроки ликвидации разницы в учебных планах.
 По итогам работы аттестационной комиссии переаттестация (перезачёт) учебных дисциплин производится приказом по Университету.
 Наличие несданных дисциплин (модулей, не пройденных практик) по истечении сроки, установленных аттестационной комиссией, приравнивается к академическим задолженностям.'),

-- 17
('Сохраняются ли зачетная книжка и студенческий билет при переходе с одной образовательной программы Университета на другую?',
 'При незначительной разнице в учебных планах (при переходе на родственную образовательную программу) обучающемуся могут быть сохранены прежние документы (зачётная книжка и студенческий билет), в которых, ссылкой на приказ о переводе, заверенной гербовой печатью, подтверждается факт перевода на другую образовательную программу. В этом случае в зачётную книжку в соответствии с приказом вносятся записи о ликвидации разницы в учебных планах и проставляются соответствующие оценки.
 При значительной разнице в учебных планах обучающемуся выдаются новые документы, подтверждающие перевод обучающегося на другую образовательную программу. В этом случае помимо записей о ликвидации разницы в учебных планах в новую зачётную книжку вносятся записи о переаттестованных (перезачтенных) дисциплинах, практиках, курсовых проектах (работах) с проставлением соответствующих оценок.'),

-- 18
('Когда начинается и заканчивается прием заявлений на перевод?',
 'Перевод обучающихся не зависит от периода (времени) учебного года и осуществляется при наличии вакантных мест для перевода.'),

-- 19
('Нужно ли сдавать экзамены при переводе?',
 'В случае если заявлений о переводе подано больше количества вакантных мест для перевода, деканат факультета / дирекция института (филиала) помимо оценивания полученных документов проводит конкурсный отбор среди лиц, подавших заявления о переводе.
 По результатам конкурсного отбора деканат факультета / дирекция института (филиала) рекомендует принять решение о зачислении на вакантные места для перевода обучающихся, наиболее подготовленных к освоению соответствующей образовательной программы, руководствуясь при этом средним баллом успеваемости, а также совокупностью и значимостью индивидуальных достижений.
 Перевод осуществляется на основе аттестации, которую проводит аттестационная комиссия принимающего факультета (института/филиала).
 Для переаттестации (перезачёта) дисциплин в деканате принимающего факультета (дирекции института/филиала) обучающемуся выдается аттестационная ведомость, в которую вносятся все дисциплины (модули, практики), подлежащие переаттестации (перезачёту).
 Аттестация может проводиться путем собеседования или в иной форме, определяемой соответствующей аттестационной комиссией факультета (института/филиала). В ходе аттестации устанавливается перечень неизученных дисциплин (разделов дисциплин, модулей, не пройденных практик), по которым обучающемуся необходимо пройти аттестационные испытания. Аттестационной комиссией определяются сроки ликвидации разницы в учебных планах.'),

-- 20
('Кто имеет право на академический отпуск?',
 'Академический отпуск предоставляется обучающимся в связи с временной невозможностью освоения ими образовательной программы в случае призыва на военную службу или заключения контракта о прохождении военной службы, по медицинским показаниям, а также в иных исключительных случаях, в том числе в связи со стихийными бедствиями, по семейным обстоятельствам.'),

-- 21
('Какой максимальный срок академического отпуска?',
 'Продолжительность академического отпуска единовременно не может превышать 12 календарных месяцев, за исключением академического отпуска в связи с прохождением военной службы или по медицинским показаниям, срок предоставления которого не может превышать 2 года.'),

-- 22
('Сколько раз можно брать академический отпуск?',
 'Количество академических отпусков, предоставляемых обучающемуся в период обучения по соответствующей образовательной программе, не ограничено.'),

-- 23
('Что нужно для оформления академического отпуска?',
 'Основанием для принятия решения о предоставлении обучающемуся академического отпуска является личное заявление обучающегося на имя проректора по учебной работе, а также документ, подтверждающий наличие оснований для академического отпуска:
 - медицинское заключение, выданное медицинской организацией, входящей в государственную или муниципальную систему здравоохранения (для предоставления академического отпуска по медицинским показаниям);
 - мобилизационное предписание, распоряжение или повестка военного комиссариата, содержащие время и место отправки к месту прохождения военной службы, копия контракта о прохождении военной службы в Вооруженных Силах Российской Федерации, заверенная в установленном законодательством Российской Федерации порядке (для предоставления академического отпуска в связи с прохождением военной службы);
 - или иной документ, подтверждающий основания предоставления академического отпуска (при наличии).'),

-- 24
('Как быть, если обучающийся не может лично представить заявление и документы, необходимые для оформления академического отпуска?',
 'В случае, если обучающийся по объективным причинам (нахождение на военной службе, медицинские показания, обстоятельства непреодолимой силы) не может лично представить заявление и необходимые документы, такое заявление может быть подано законным представителем обучающегося, либо лицом по доверенности, выданной указанному лицу обучающимся, либо через операторов почтовой связи общего пользования заказным почтовым отправлением с уведомлением о вручении, а также иным доступным способом.'),

-- 25
('Можно ли оформить академический отпуск в том случае, если обучающийся не может представить документы, подтверждающие наличие основания для него?',
 'Да, можно. Для принятия решения о предоставлении академического отпуска по исключительным обстоятельствам, а также в случаях, когда обучающийся не может представить документы, подтверждающие основания предоставления академического отпуска, приказом ректора утверждается Комиссия.
 В результате рассмотрения заявления, а также прилагаемых к нему документов (при наличии) Комиссия принимает решение о предоставлении обучающемуся академического отпуска или об отказе в его предоставлении.'),

-- 26
('Может ли студент, находясь в академическом отпуске, посещать занятия?',
 'Нет. Обучающийся в период нахождения в академическом отпуске освобождается от обязанностей, связанных с освоением им образовательной программы в Университете, и не допускается к образовательному процессу до завершения академического отпуска.'),

-- 27
('Может ли студент прервать академический отпуск?',
 'Да, может. Академический отпуск может быть завершен до окончания периода времени, на который он был предоставлен, на основании заявления обучающегося. В таком случае обучающийся допускается к обучению на основании приказа проректора по учебной работе.'),

-- 28
('Нужно ли платить за обучение во время академического отпуска?',
 'Нет. В случае, если обучающийся обучается по договору об образовании за счет средств физического и (или) юридического лица, во время академического отпуска плата за обучение с него не взимается.'),

-- 29
('Что делать, если на момент возвращения студента из академического отпуска образовательная программа, по которой он обучался, не реализуется?',
 'Если образовательная программа по соответствующей форме обучения, направленности (профилю), специализации, направлению подготовки на момент выхода обучающегося из академического отпуска не реализуется, обучающемуся при выходе из отпуска предлагается перевод на иную форму обучения либо образовательную программу с сохранением бюджетной (при наличии мест) / платной основы обучения.'),

-- 30
('Кто имеет право на обучение по индивидуальному графику?',
 'Обучающиеся имеют право на обучение (посещение учебных занятий) по индивидуальному графику, если они:
 - имеют детей до 3 лет и оформили отпуск по уходу за ребенком с одновременным обучением по индивидуальному графику;
 - находятся в отпуске по беременности и родам;
 - имеют соответствующие медицинские показания, подтвержденные справкой медицинского учреждения;
 - совмещают учебу с работой по профилю своего направления подготовки (специальности), приобретают опыт практической профессиональной деятельности и не имеют академических задолженностей.'),

-- 31
('Как получить зачет «автоматом»?',
 'В качестве поощрения в соответствии с Положением о БРС преподаватель имеет право выставлять отдельным обучающимся зачет по результатам текущего контроля без самой процедуры сдачи зачета.'),

-- 32
('Сколько времени студенту дается на подготовку устного ответа на экзамене?',
 'Время подготовки устного ответа должно составлять не менее 30 минут, а время ответа обучающегося – не более 15 минут.'),

-- 33
('Может ли быть перенесен срок экзаменационной сессии студенту-заочнику?',
 'Обучающимся заочной формы обучения может быть перенесен срок экзаменационной сессии только по уважительным причинам (болезнь, семейные обстоятельства, участие в российских или международных соревнованиях, командировка и др.) при наличии подтверждающих документов. В таких случаях деканом факультета/директором института (филиала) устанавливаются индивидуальные сроки предоставления дополнительного учебного отпуска.'),

-- 34
('Как можно сдать сессию досрочно?',
 'В случае сдачи сессии ранее установленных сроков обучающийся пишет заявление на имя проректора по учебной работе, в котором указываются причины переноса сроков (обязательно наличие подтверждающих документов). Заявление, на котором указаны индивидуальные сроки сессии (начало и окончание сессии), предварительно визируется деканом факультета/директором института (филиала) (заместителем декана/директора по учебной работе) и начальником (заместителем начальника) учебно-методического управления. В случае положительного решения деканатом/дирекцией готовится приказ установленного образца. Обучающемуся выдаются экзаменационные листы на каждый экзамен (зачет), которые в день сдачи экзамена (зачета) обязательно возвращаются в деканат/дирекцию. Обучающемуся может выдаваться единый лист на все экзамены (зачеты), в котором указывается срок действия единого листа. Досрочная сдача сессии разрешается не ранее чем за один месяц до окончания теоретического обучения текущего семестра.'),

-- 35
('Кто имеет право продлить сессию?',
 'Обучающийся, находившийся в период промежуточной аттестации на стационарном или амбулаторном лечении, имеет право на ее продление.'),

-- 36
('Куда нужно обратиться студенту, чтобы продлить сессию?',
 'В таких случаях обучающийся должен обратиться в течение 2 дней после закрытия листа нетрудоспособности (больничного листа) в деканат (дирекцию) с заявлением установленного образца. Приказ об установлении индивидуальных сроков промежуточной аттестации оформляется деканатом факультета/дирекцией института (филиала).'),

-- 37
('На какой период можно продлить сессию?',
 'Промежуточная аттестация продлевается на срок, указанный в подтверждающем документе (заключение врачебной комиссии медицинского учреждения и (или) справка установленного образца).'),

-- 38
('Что будет, если студент не придет на экзамен?',
 'Обучающийся, не явившийся по уважительной причине на экзамен в установленные сроки, обязан представить в деканат/дирекцию оправдательные документы (в течение двух дней с момента устранения причины отсутствия). В деканате/дирекции обучающемуся выдают экзаменационные листы на сдачу экзамена/зачета. При отсутствии официальных документов на момент окончания сессии причина неявки на экзамен (зачет) считается неуважительной. Обучающийся считается имеющим академическую задолженность.'),

-- 39
('Сколько раз можно пересдавать зачет/экзамен?',
 'Обучающиеся, имеющие академическую задолженность, вправе пройти повторную промежуточную аттестацию не более двух раз в установленные сроки (во второй раз на комиссии).'),

-- 40
('Когда можно пересдать зачет/экзамен?',
 'Повторная промежуточная аттестация проводится как в период каникул, так и в период освоения образовательной программы. В указанный период не включается время болезни обучающегося, его нахождение в академическом отпуске или отпуске по беременности и родам.'),

-- 41
('Что делать, если не выполнил программу практики по уважительной причине?',
 'Обучающиеся, не выполнившие программу практики по уважительной причине, направляются на практику повторно в свободное от учебы время при условии согласия базы практики принять обучающегося для прохождения практики.'),

-- 42
('Можно ли пересдать экзамен на более высокую оценку?',
 'Пересдача экзаменов (дифференцированных зачетов) в период сессии на более высокую оценку не допускается. Экзаменационный лист не выдается при наличии в экзаменационной (зачетной) ведомости положительной оценки.
 Обучающиеся имеют возможность пересдать экзамены (дифференцированные зачеты) (не более 3) на более высокую оценку в период после сдачи последней сессии и, как правило, после прохождения всех практик до начала итоговых аттестационных испытаний по решению проректора по учебной работе при согласии декана факультета/директора института (филиала) и начальника (заместителя начальтеля) учебно-методического управления. Обучающийся должен подать заявление на пересдачу на имя проректора по учебной работе с указанием дисциплины (модуля) и имеющейся оценки по данной дисциплине (модулю).'),

-- 43
('Можно ли пересдать курсовую работу?',
 'Нет. Не допускается пересдача курсовых работ (проектов) и практик.'),

-- 44
('Что такое индивидуальный график?',
 'Индивидуальный график обучения (посещения занятий) представляет собой форму организации обучения студента, при которой часть дисциплин (дисциплины) учебного плана образовательной программы осваиваются обучающимся самостоятельно. Обучение по индивидуальному графику не отменяет для обучающегося выполнение в полном объеме работ, предусмотренных рабочими программами дисциплин (практик) и программы итоговой аттестации.'),

-- 45
('Когда можно оформить индивидуальный график?',
 'Обучающимся, осваивающим образовательные программы бакалавриата или специалитета, индивидуальный график предоставляется после первого семестра; обучающимся, осваивающим образовательные программы магистратуры – с первого семестра.'),

-- 46
('Как оформить индивидуальный график?',
 'Для оформления индивидуального графика обучения (посещения занятий) обучающийся должен написать заявление на имя проректора по учебной работе. К заявлению прилагаются индивидуальный учебный график, и индивидуальные графики прохождения контрольных мероприятий (индивидуальные рейтинг-планы дисциплин), учитывающие индивидуальный график обучения студента (посещения занятий). Индивидуальный учебный график, индивидуальные рейтинг-планы дисциплин (модулей) согласовываются с преподавателями, ведущими соответствующие дисциплины (модули).'),

-- 47
('Могут ли отчислить из-за пропусков?',
 'Студент, не посещающий учебные занятия без уважительных причин в течение 30 (тридцати) календарных дней подряд, или не присутствующий без уважительных причин на 25% учебных занятий по отдельным дисциплинам, предусмотренным учебным планом или индивидуальным учебным планом в семестре (триместре), может быть отчислен из Университета как невыполняющий обязанности по добросовестному освоению образовательной программы и выполнению учебного плана.
 Основанием для отчисления являются документы, подтверждающие факт невыполнения обучающимся обязанностей по добросовестному освоению образовательной программы и выполнению учебного плана (служебная записка декана факультета / директора института, иные документы).');
